    private void showOnlineListDialog(){ android.app.Dialog dialog=makeFullScreenDialog(); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setBackgroundColor(Color.WHITE); root.setPadding(24,20,24,24); LinearLayout top=new LinearLayout(this); top.setOrientation(LinearLayout.HORIZONTAL); top.setGravity(Gravity.CENTER_VERTICAL); root.addView(top); TextView title=new TextView(this); title.setText("Online list"); title.setTextColor(Color.parseColor("#222222")); title.setTextSize(19); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f)); top.addView(title); TextView close=new TextView(this); close.setText("✕"); close.setTextSize(22); close.setTextColor(Color.parseColor("#888888")); close.setPadding(10,10,10,10); close.setOnClickListener(v->dialog.dismiss()); top.addView(close); ScrollView sv=new ScrollView(this); LinearLayout list=new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); sv.addView(list); root.addView(sv);
        // REALTIME - online_users theke, tarpor users theke REAL profile nibo
        databaseReference.child("online_users").addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ list.removeAllViews(); if(!s.exists()||s.getChildrenCount()==0){ TextView tv=new TextView(VoiceRoomActivity.this); tv.setText("No one online"); tv.setTextColor(Color.parseColor("#AAAAAA")); tv.setGravity(Gravity.CENTER); tv.setPadding(0,40,0,40); list.addView(tv); return; } for(DataSnapshot ds:s.getChildren()){ String uidKey=ds.getKey(); // 9-digit ID
            // 1) online_users e ja save ase oita age nao
            String onName=ds.child("name").getValue(String.class); String onPhoto=ds.child("photoBase64").getValue(String.class); String onCountry=ds.child("country").getValue(String.class); String onGender=ds.child("gender").getValue(String.class); String onLevel=ds.child("level").getValue(String.class);
            // 2) users theke REAL profile diye overwrite koro - GROUP PHOTO kokhono asbe na
            userDatabaseRef.orderByChild("my9DigitId").equalTo(uidKey).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot us){ String nm=onName!=null?onName:"User"; String ph=onPhoto!=null?onPhoto:""; String co=onCountry!=null?onCountry:""; String ge=onGender!=null?onGender:"Male"; String lv=onLevel!=null?onLevel:"0"; if(us.exists()){ for(DataSnapshot u:us.getChildren()){ if(u.child("name").getValue()!=null) nm=String.valueOf(u.child("name").getValue()); if(u.child("photoBase64").getValue()!=null && !String.valueOf(u.child("photoBase64").getValue()).isEmpty()) ph=String.valueOf(u.child("photoBase64").getValue()); if(u.child("country").getValue()!=null) co=String.valueOf(u.child("country").getValue()); if(u.child("gender").getValue()!=null) ge=String.valueOf(u.child("gender").getValue()); if(u.child("level").getValue()!=null) lv=String.valueOf(u.child("level").getValue()); break; } } addOnlineRow(list, uidKey, nm, ph, lv, ge, co, dialog); } @Override public void onCancelled(@NonNull DatabaseError e){ addOnlineRow(list, uidKey, onName!=null?onName:"User", onPhoto!=null?onPhoto:"", "0", "Male", "", dialog); } });
        } } @Override public void onCancelled(@NonNull DatabaseError e){} }); dialog.setContentView(root); dialog.show(); }
