    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState); setContentView(R.layout.activity_voice_room);
        prefs=getSharedPreferences("SR_PREFS",MODE_PRIVATE);
        currentUserId=prefs.getString("USER_ID",""); my9DigitId=prefs.getString("USER_9DIGIT_ID",""); myDisplayName=prefs.getString("USER_NAME","User"); myCountry=prefs.getString("USER_COUNTRY","Bangladesh"); myLanguage=prefs.getString("USER_LANGUAGE","English"); myPhotoBase64=prefs.getString("USER_PHOTO_BASE64","");
        String rid=getIntent().getStringExtra("ROOM_OWNER_ID"); if(rid!=null && !rid.isEmpty()) roomOwnerId=rid; String rname=getIntent().getStringExtra("ROOM_NAME"); String fromRoom=getIntent().getStringExtra("FROM_ROOM");
        databaseReference=com.google.firebase.database.FirebaseDatabase.getInstance().getReference(); userDatabaseRef=databaseReference.child("users"); roomMetaRef=databaseReference.child("rooms").child(roomOwnerId).child("meta"); adminsRef=databaseReference.child("rooms").child(roomOwnerId).child("admins"); messagesRef=databaseReference.child("rooms").child(roomOwnerId).child("messages");
        roomTitleText=findViewById(R.id.roomTitleText); roomInfoText=findViewById(R.id.roomInfoText); roomNoticeBarText=findViewById(R.id.roomNoticeBarText); textOnlineCount=findViewById(R.id.textOnlineCount); textRoomCoins=findViewById(R.id.textRoomCoins); roomHeaderProfileImg=findViewById(R.id.roomHeaderProfileImg); inputChatMessage=findViewById(R.id.inputChatMessage); btnChatOption=findViewById(R.id.btnChatOption); chatListContainer=findViewById(R.id.chatListContainer); chatScrollView=findViewById(R.id.chatScrollView); chatPopupBar=findViewById(R.id.chatPopupBar);
        if(chatPopupBar!=null) chatPopupBar.setVisibility(View.GONE); // SURUTE POPUP BONDHO - AUTOMATIC ASBE NA
        if(roomTitleText!=null && rname!=null && !rname.isEmpty()) roomTitleText.setText(rname); if(roomInfoText!=null) roomInfoText.setText("ID: "+roomOwnerId);
        galleryLauncher=registerForActivityResult(new ActivityResultContracts.StartActivityForResult(), result->{ if(result.getResultCode()==RESULT_OK && result.getData()!=null && result.getData().getData()!=null){ try{ Bitmap bmp=MediaStore.Images.Media.getBitmap(getContentResolver(), result.getData().getData()); Bitmap small=Bitmap.createScaledBitmap(bmp, 400, 400, true); java.io.ByteArrayOutputStream baos=new java.io.ByteArrayOutputStream(); small.compress(Bitmap.CompressFormat.JPEG, 70, baos); String b64=Base64.encodeToString(baos.toByteArray(), Base64.DEFAULT); if("ROOM_LOGO".equals(galleryMode)){ pendingRoomPhotoBase64=b64; if(roomEditLogoView!=null){ roomEditLogoView.setImageBitmap(small); } if(roomEditLogoText!=null) roomEditLogoText.setVisibility(View.GONE); Toast.makeText(this,"Room Photo Selected ✅ - Save koro",Toast.LENGTH_SHORT).show(); } else if("CUSTOM_BG".equals(galleryMode)){ pendingCustomBgBase64=b64; Toast.makeText(this,"Background Selected ✅ - Room set e Save koro",Toast.LENGTH_SHORT).show(); } }catch(Exception e){ Toast.makeText(this,"Image nite parlam na",Toast.LENGTH_SHORT).show(); } } });
        if(roomHeaderProfileImg!=null) roomHeaderProfileImg.setOnClickListener(v->showHeaderProfileMembersDialog());
        if(roomTitleText!=null) roomTitleText.setOnClickListener(v->showHeaderProfileMembersDialog());
        View btnOnline=findViewById(R.id.btnOnlineList); if(btnOnline!=null) btnOnline.setOnClickListener(v->showOnlineListDialog());
        if(textOnlineCount!=null) textOnlineCount.setOnClickListener(v->showOnlineListDialog());
        View btnPower=findViewById(R.id.btnPower); if(btnPower!=null) btnPower.setOnClickListener(v->showExitDialog());
        View btnRank=findViewById(R.id.btnInRoomRanking); if(btnRank!=null) btnRank.setOnClickListener(v->showInRoomRankingDialog());
        View btnGift=findViewById(R.id.btnGiftBox); if(btnGift!=null) btnGift.setOnClickListener(v->showNewGiftPanel());
        View btnGame=findViewById(R.id.btnGame); if(btnGame!=null) btnGame.setOnClickListener(v->Toast.makeText(this,"Game - Coming Soon 🎮",Toast.LENGTH_SHORT).show());
        View btnTools=findViewById(R.id.btnRoomTools); if(btnTools!=null) btnTools.setOnClickListener(v->showIconToolsDialog(currentUserId.equals(roomOwnerId)||my9DigitId.equals(roomOwnerId)));
        View btnMic=findViewById(R.id.btnMicToggle); if(btnMic!=null) btnMic.setOnClickListener(v->Toast.makeText(this,"Mic - Coming Soon 🎤",Toast.LENGTH_SHORT).show());
        setupChatPopup(); listenToChatRealtime(); listenToRoomPhoto(); listenToRoomDetails(); listenToRoomTheme(); listenToRoomAdmins(); listenToMyWallet(); listenToOnlineMembers(); syncLatestUserProfile(); setupSeatInteractions(); listenToFirebaseSeats(); applyRoomBackground();
    }
